 for(const mode of ['busy','late-status','late-inspect','late-task','cross-target','wrong-status-id'])await check('deployment-snapshot-ownership-'+mode,async p=>{
  await p.evaluate(mode=>{
   const config={target:'local',projectId:'project',targetId:'env',inputSource:'local',directoryName:'test',maxSeconds:60,gpu:0,resources:{queue:'',cpus:1,gpus:1,memory_mb:4096}};
   const result=id=>({...window.__test.run,id,snapshots:[{name:'run.py',sha256:id+'-hash',size:id==='old'?1:2}]});
   window.__test.task={id:'race',name:'Snapshot ownership',parameters:{engine:'pydyn.md'},parameterRevision:1,review:{status:'ready',parameterRevision:1},deployment:{revision:1,config,prepared:{artifactId:'old',parameterRevision:1,deploymentRevision:1}}};
   window.__test.responses={
    '/api/run/status':request=>{
     const id=request.data.run_id;
     if(id==='old'&&['late-status','late-task','cross-target'].includes(mode))return new Promise(resolve=>window.__test.finishOld=()=>resolve(result('old')));
     return result(mode==='wrong-status-id'?'unexpected':id);
    },
    '/api/cluster/status':request=>({...result(request.data.run_id),kind:'cluster-run'}),
    '/api/run/input':()=>new Promise(resolve=>window.__test.finishInspect=()=>resolve({name:'run.py',sha256:'old-hash',text:'STALE_PREVIEW_TEXT'}))
   };
   if(mode==='cross-target'){window.__test.project.policy.clusters=['env'];window.__test.responses['/api/clusters']=()=>[{id:'env',name:'Synthetic remote target'}];}
   const original=window.studio.invoke;
   window.studio.invoke=async(method,data)=>{
    if(method==='task.linkRun')return window.__test.task;
    if(method==='task.deployment.save')return new Promise(resolve=>{
     const finish=()=>{window.__test.task={...window.__test.task,deployment:{...window.__test.task.deployment,revision:2}};resolve(window.__test.task);};
     if(mode==='busy')window.__test.finishSave=finish;else finish();
    });
    if(method==='task.deployment.prepare'){window.__test.task={...window.__test.task,deployment:{...window.__test.task.deployment,prepared:{artifactId:'new',parameterRevision:1,deploymentRevision:2}}};return result('new');}
    return original(method,data);
   };
   window.props={task:window.__test.task,worker:true,projects:[window.__test.project],environments:[window.__test.environment],onTask:()=>{},onRun:()=>{},onError:e=>window.__test.error=String(e),onRefresh:()=>window.renderTest('DeploymentPanel',{...window.props,task:window.__test.task})};
   return window.renderTest('DeploymentPanel',window.props);
  },mode);
  if(mode==='wrong-status-id'){
   await p.waitForFunction(()=>window.__test.calls.some(c=>c.data?.target==='/api/run/status'));await p.waitForTimeout(100);
   assert.equal(await p.getByTestId('review-input-snapshots').count(),0);assert.equal(await p.getByTestId('execute-deployment').isDisabled(),true);
  }else{
   if(['late-status','late-task','cross-target'].includes(mode))await p.waitForFunction(()=>window.__test.finishOld);else await p.getByTestId('review-input-snapshots').waitFor();
   if(mode==='late-inspect'){
    await p.locator('.input-snapshot-list button').click();await p.waitForFunction(()=>window.__test.finishInspect);
    await p.evaluate(()=>{window.__test.task={...window.__test.task,deployment:{...window.__test.task.deployment,revision:2,prepared:{artifactId:'new',parameterRevision:1,deploymentRevision:2}}};return window.renderTest('DeploymentPanel',{...window.props,task:window.__test.task});});
   }else if(mode==='late-task'||mode==='cross-target'){
    await p.evaluate(mode=>{window.__test.task={...window.__test.task,id:'other-task',deployment:{...window.__test.task.deployment,config:{...window.__test.task.deployment.config,target:mode==='cross-target'?'cluster':'local',resources:{...window.__test.task.deployment.config.resources,queue:mode==='cross-target'?'short':''}},prepared:{artifactId:'new',parameterRevision:1,deploymentRevision:1}}};return window.renderTest('DeploymentPanel',{...window.props,task:window.__test.task});},mode);
   }else{
    await p.getByTestId('prepare-deployment').click();
    if(mode==='busy'){
     await p.waitForFunction(()=>window.__test.finishSave);assert.equal(await p.getByTestId('review-input-snapshots').count(),0);assert.equal(await p.getByTestId('execute-deployment').isDisabled(),true);await p.evaluate(()=>window.__test.finishSave());
    }
   }
   await p.waitForFunction(()=>document.querySelector('.deployment-page')?.textContent?.includes('new-hash'));
   await p.waitForFunction(()=>!document.querySelector('[data-testid=review-input-snapshots]')?.disabled);
   await p.getByTestId('review-input-snapshots').check();assert.equal(await p.getByTestId('execute-deployment').isDisabled(),false);
   if(mode==='late-inspect')await p.evaluate(()=>window.__test.finishInspect());else if(['late-status','late-task','cross-target'].includes(mode))await p.evaluate(()=>window.__test.finishOld());
   await p.waitForTimeout(100);await p.locator('.snapshot-input-identity summary').click();assert.match(await p.locator('.input-snapshot-list').innerText(),/new-hash/);assert.doesNotMatch(await p.locator('.deployment-page').innerText(),/STALE_PREVIEW_TEXT|old-hash/);assert.equal(await p.getByTestId('review-input-snapshots').isChecked(),true);assert.equal(await p.getByTestId('execute-deployment').isDisabled(),false);
   if(mode==='cross-target'){assert.equal(await p.evaluate(()=>window.__test.calls.some(c=>c.data?.target==='/api/cluster/status'&&c.data.data?.run_id==='new')),true);assert.equal(await p.evaluate(()=>window.__test.calls.some(c=>c.data?.target==='/api/run/status'&&c.data.data?.run_id==='new')),false);}
  }
  assert.equal(await p.evaluate(()=>window.__test.calls.some(c=>c.method==='task.execute')),false);
 });

